import sqlite3
from flask import Flask, jsonify, request

MAX_PAGE_SIZE = 100


def _positive_int_arg(name: str, default: int):
    """Parse a query param that must be a positive integer when supplied.

    Returns (value, None) on success or (None, (response, status)) on failure.
    """
    raw = request.args.get(name)
    if raw is None:
        return default, None
    try:
        value = int(raw)
    except (TypeError, ValueError):
        return None, (jsonify(error=f"'{name}' must be a positive integer"), 400)
    if value < 1:
        return None, (jsonify(error=f"'{name}' must be a positive integer"), 400)
    return value, None


@app.get("/items")
def list_items():
    page, err = _positive_int_arg("page", default=1)
    if err:
        return err
    page_size, err = _positive_int_arg("page_size", default=20)
    if err:
        return err
    page_size = min(page_size, MAX_PAGE_SIZE)  # hard cap at 100

    offset = (page - 1) * page_size
    db = get_db()  # existing sqlite3 connection helper
    rows = db.execute(
        "SELECT id, name FROM items ORDER BY id LIMIT ? OFFSET ?",
        (page_size, offset),
    ).fetchall()
    total = db.execute("SELECT COUNT(*) FROM items").fetchone()[0]

    result = {
        "items": rows,
        "page": page,
        "page_size": page_size,
        "total": total,
    }
    return jsonify(result), 200
